import {createWorkoutDraft,createPeriodDraft} from '../../src/features/entry/draftReducer'
import type {ExerciseOptionV2,ExercisePreviewV2,ExercisePreviewV2Request,SubmissionReceiptV2} from '../../src/api/contracts'
import type {EntrySubmissionV2} from '../../src/api/submissionsV2'
import {user} from './profile'
/** Synthetic controlled responses only; no provider or official-source verification claim. */
export const strengthOptionV2:ExerciseOptionV2={id:'201',optionKey:'synthetic-strength',revision:'r1',displayName:'Synthetic strength',category:'STRENGTH',periodKind:'STRENGTH',mappingKind:'GENERAL_ACTIVITY_ESTIMATE',allowedDetails:[],referenceId:'301',mappingReason:'Synthetic fixture only'}
export const cardioOptionV2:ExerciseOptionV2={...strengthOptionV2,id:'202',optionKey:'synthetic-cardio',displayName:'Synthetic cardio',category:'CARDIO',periodKind:'ACTIVITY',mappingKind:'UNAVAILABLE',referenceId:null}
export const ballOptionV2:ExerciseOptionV2={...strengthOptionV2,id:'203',optionKey:'synthetic-ball',displayName:'Synthetic basketball',category:'SPORTS',periodKind:'ACTIVITY',mappingKind:'SPECIFIC_REFERENCE'}
export function workoutV2Draft(){const draft=createWorkoutDraft(user.id,'2020-01-02','MANUAL');draft.periods[0].selection={kind:'OPTION',option:strengthOptionV2};draft.periods[0].durationMinutesInput='50';const second=createPeriodDraft('ACTIVITY');second.selection={kind:'OPTION',option:cardioOptionV2};second.durationMinutesInput='20';draft.periods.push(second);return draft}
export function exercisePreviewFixtureV2(input:ExercisePreviewV2Request):ExercisePreviewV2{const inputPeriods=input.entry.kind==='QUICK'?[input.entry.period]:input.entry.periods,periods=inputPeriods.map(p=>({clientEntryId:p.clientEntryId,durationMinutes:p.durationMinutes,status:p.optionId==='202'?'NO_APPLICABLE_REFERENCE' as const:'AVAILABLE' as const,estimatedKj:p.optionId==='202'?null:1000,calculationFingerprint:(p.optionId==='202'?'b':'a').repeat(64),unavailableReason:p.optionId==='202'?'No applicable synthetic test reference.':null})),known=periods.filter(p=>p.estimatedKj!==null);return {periods,totalMinutes:periods.reduce((n,p)=>n+p.durationMinutes,0),knownEnergyKj:known.length?known.reduce((n,p)=>n+p.estimatedKj!,0):null,partial:known.length>0&&known.length<periods.length,fingerprint:'c'.repeat(64),inputSignature:'d'.repeat(64)}}
export function exerciseProofFixtureV2(envelope:EntrySubmissionV2):SubmissionReceiptV2{if(envelope.domain!=='EXERCISE')throw Error('Expected exercise');const {entry}=envelope.payload,periods=entry.kind==='QUICK'?[entry.period]:entry.periods;return {schemaVersion:2,submissionId:envelope.payload.submissionId,kind:'EXERCISE_ENTRY_V2',committedAt:'2020-01-02T01:00:00Z',replayed:false,roots:[{kind:entry.kind,id:'9',clientEntryId:entry.clientEntryId,recordDate:envelope.payload.recordDate,versionAtCreation:0}],leaves:periods.map((p,index)=>({kind:'ACTIVITY_PERIOD',id:entry.kind==='QUICK'?'9':String(10+index),clientEntryId:p.clientEntryId,rootClientEntryId:entry.clientEntryId,recordDate:envelope.payload.recordDate,versionAtCreation:0}))}}
